using namespace dandrum::sampler;
#define REQUIRE(x) do { ++assertions; if (!(x)) throw std::runtime_error(std::string(__func__)+":"+std::to_string(__LINE__)+": " #x); } while(false)
static int assertions=0, groups=0;
static void ready(Model& m) { m.tick(2.0); }
static void history() {
 Model noOp;noOp.command("patch.load","kit");double displayed=static_cast<float>(noOp.number("amp-sustain"));REQUIRE(noOp.gesture("amp-sustain",0,displayed));REQUIRE(noOp.gesture("amp-sustain",2,displayed));REQUIRE(noOp.undoCount()==0);REQUIRE(noOp.number("amp-sustain")==.68);
 Model m; REQUIRE(m.text("patch-id")=="empty"); REQUIRE(m.command("patch.load","kit"));
 double v=m.number("cutoff"); REQUIRE(m.gesture("cutoff",0,v)); REQUIRE(m.gesture("cutoff",1,1000)); REQUIRE(m.gesture("cutoff",1,2000)); REQUIRE(m.gesture("cutoff",2,2000)); REQUIRE(m.undoCount()==1); REQUIRE(m.number("cutoff")==2000);
 REQUIRE(m.command("undo")); REQUIRE(m.number("cutoff")==v); REQUIRE(m.command("redo")); REQUIRE(m.number("cutoff")==2000);
 REQUIRE(m.gesture("cutoff",0,2000)); REQUIRE(m.gesture("cutoff",1,500)); REQUIRE(m.gesture("cutoff",3,500)); REQUIRE(m.number("cutoff")==2000); REQUIRE(m.undoCount()==1); REQUIRE(!m.command("invented-action")); ++groups;
}
static void patch() {
 Model m; REQUIRE(m.command("patch.load","keys")); REQUIRE(m.records("zone").size()==10); REQUIRE(m.command("tree.rename","keys","Edited Keys")); REQUIRE(m.find("tree","keys")->text("name")=="Edited Keys"); REQUIRE(m.command("tree.duplicate","keys")); REQUIRE(m.records("tree").size()>3); std::string d=m.definition(); Model n; REQUIRE(n.importDefinition(d)); REQUIRE(n.definition()==d); std::string saved=n.definition(); REQUIRE(!n.importDefinition("not a patch")); REQUIRE(n.definition()==saved); REQUIRE(m.command("patch.load","hybrid")); REQUIRE(m.records("module").size()>=4); REQUIRE(m.command("patch.favourite","kit")); REQUIRE(m.find("preset","kit")->number("favourite")==0); ++groups;
}
static std::filesystem::path wav() { auto p=std::filesystem::temp_directory_path()/"dandrum-model-test.wav"; std::ofstream f(p,std::ios::binary); auto u16=[&](unsigned x){f.put(x&255);f.put((x>>8)&255);};auto u32=[&](unsigned x){u16(x&65535);u16(x>>16);}; f.write("RIFF",4);u32(44);f.write("WAVEfmt ",8);u32(16);u16(1);u16(1);u32(4);u32(8);u16(2);u16(16);f.write("data",4);u32(8);u16(0);u16(16384);u16(32768);u16(32767);return p; }
static void assets() {
 Model m; auto p=wav(); REQUIRE(m.command("asset.import","",p.string())); REQUIRE(m.text("asset-state")=="loading"); ready(m); REQUIRE(m.text("asset-state")=="loaded"); auto a=m.records("source").front(); REQUIRE(a.number("frames")==4); REQUIRE(a.number("duration")==1); REQUIRE(m.peaks().size()==4); REQUIRE(std::abs(m.peaks()[1].maximum-0.5)<0.001); REQUIRE(m.peaks()[2].minimum==-1);
 REQUIRE(m.command("sample.set","region-start","",0.2)); REQUIRE(m.command("sample.set","region-end","",0.8)); REQUIRE(m.command("sample.set","loop-start","",0.3)); REQUIRE(m.command("sample.set","loop-end","",0.7)); REQUIRE(m.command("sample.set","fade-in","",0.1)); REQUIRE(m.command("sample.set","reversed","",1)); REQUIRE(m.number("region-start")==0.2); REQUIRE(m.records("history").size()>=6);
 auto h=m.records("history")[4].id; REQUIRE(m.command("sample.history-bypass",h)); REQUIRE(m.number("fade-in")==0); REQUIRE(m.command("sample.history-bypass",h)); REQUIRE(m.number("fade-in")==0.1);
 auto id=a.id; REQUIRE(m.command("asset.relink",id,p.string()+".missing"));ready(m); REQUIRE(m.text("asset-state")=="missing");REQUIRE(m.command("asset.relink",id,p.string()));ready(m);REQUIRE(m.text("asset-state")=="loaded");REQUIRE(m.command("sample.freeze",id));ready(m);REQUIRE(m.find("source",id)->number("frozen")==1); std::filesystem::remove(p); ++groups;
}
static void analysis() {
 Model m;m.command("patch.load","kit"); REQUIRE(m.command("analysis.start","transients"));REQUIRE(m.text("analysis-state")=="running");auto old=m.records("slice").size();ready(m); REQUIRE(m.text("analysis-state")=="done");REQUIRE(m.records("slice").size()==old);REQUIRE(m.records("analysis").size()>=2);auto expected=m.records("analysis").size();REQUIRE(m.command("analysis.apply"));REQUIRE(m.records("slice").size()==expected);REQUIRE(m.command("slice.split",m.records("slice")[0].id,"",0.05));REQUIRE(m.command("undo"));REQUIRE(m.command("analysis.start","pitch"));REQUIRE(m.command("analysis.cancel"));ready(m);REQUIRE(m.text("analysis-state")=="idle"); REQUIRE(m.command("analysis.fail","loops"));ready(m);REQUIRE(m.text("analysis-state")=="failed");REQUIRE(m.command("analysis.retry"));ready(m);REQUIRE(m.text("analysis-state")=="done");REQUIRE(m.command("analysis.discard"));REQUIRE(m.records("analysis").empty()); ++groups;
}
