 REQUIRE(m.command("macro.bind","tone","cutoff",0.5));REQUIRE(m.command("macro.set","tone","",0.8));REQUIRE(m.find("macro","tone")->number("value")==0.8);REQUIRE(m.command("macro.host","tone","",1));REQUIRE(m.find("macro","tone")->number("host")==1);REQUIRE(m.command("routing.output","kick","Drums 3/4"));REQUIRE(m.find("tree","kick")->text("output")=="Drums 3/4");REQUIRE(m.command("send.set","kick","Reverb",0.6));REQUIRE(m.find("send","kick:Reverb")->number("value")==0.6); REQUIRE(m.command("fx.add","main","Reverb"));id=m.records("fx").back().id;REQUIRE(m.command("fx.bypass",id));REQUIRE(m.find("fx",id)->number("bypassed")==1);REQUIRE(m.command("inherit.override","kick","pan",0.25));REQUIRE(m.effective("kick","pan")==0.25);REQUIRE(m.command("inherit.reset","kick","pan"));REQUIRE(m.effective("kick","pan")==0);++groups;
