static void lifecycle() {
 Model m;m.command("patch.load","kit");REQUIRE(m.noteOn(38,120,"pad"));REQUIRE(m.noteOn(38,100,"keys"));REQUIRE(m.heldNotes().size()==1);m.noteOff(38,"pad");REQUIRE(m.heldNotes().size()==1);m.noteOff(38,"keys");REQUIRE(m.heldNotes().empty());m.command("pc.enabled","","",1);REQUIRE(!m.pcKey("a",true,true,false));REQUIRE(m.pcKey("a",true,false,false));REQUIRE(m.pcKey("a",true,false,false));REQUIRE(m.heldNotes().size()==1);m.command("pc.octave","","",12);REQUIRE(!m.pcKey("a",false,true,true));REQUIRE(m.heldNotes().empty()); REQUIRE(m.noteOn(127,100,"unmapped"));REQUIRE(m.records("diagnostic").back().text("detail").find("Silent")!=std::string::npos);m.releaseNotes();REQUIRE(m.heldNotes().empty()); for(int i=0;i<200;++i) m.noteOn(38,100,"repeat"); REQUIRE(m.records("event").size()<=128);m.command("patch.load","empty");REQUIRE(m.heldNotes().empty());++groups;
}
